<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Client\Domain;

final class DynamicClientRequest
{
    public function __construct(
        public readonly array $redirectUris,
        public readonly ?string $clientName = null,
        public readonly array $grantTypes = ['authorization_code'],
        public readonly array $responseTypes = ['code'],
        public readonly ?string $scope = null,
        public readonly string $tokenEndpointAuthMethod = 'client_secret_basic',
        public readonly ?string $logoUri = null,
        public readonly ?string $clientUri = null,
        public readonly ?string $policyUri = null,
        public readonly ?string $tosUri = null,
        public readonly ?string $backchannelLogoutUri = null,
        public readonly ?string $frontchannelLogoutUri = null,
    ) {
    }

    public static function fromArray(array $data): self
    {
        if (empty($data['redirect_uris']) || !is_array($data['redirect_uris'])) {
            throw new \InvalidArgumentException('redirect_uris is required and must be an array');
        }

        return new self(
            redirectUris: $data['redirect_uris'],
            clientName: isset($data['client_name']) ? (string) $data['client_name'] : null,
            grantTypes: isset($data['grant_types']) && is_array($data['grant_types'])
                ? $data['grant_types']
                : ['authorization_code'],
            responseTypes: isset($data['response_types']) && is_array($data['response_types'])
                ? $data['response_types']
                : ['code'],
            scope: isset($data['scope']) ? (string) $data['scope'] : null,
            tokenEndpointAuthMethod: isset($data['token_endpoint_auth_method'])
                ? (string) $data['token_endpoint_auth_method']
                : 'client_secret_basic',
            logoUri: isset($data['logo_uri']) ? (string) $data['logo_uri'] : null,
            clientUri: isset($data['client_uri']) ? (string) $data['client_uri'] : null,
            policyUri: isset($data['policy_uri']) ? (string) $data['policy_uri'] : null,
            tosUri: isset($data['tos_uri']) ? (string) $data['tos_uri'] : null,
            backchannelLogoutUri: isset($data['backchannel_logout_uri']) ? (string) $data['backchannel_logout_uri'] : null,
            frontchannelLogoutUri: isset($data['frontchannel_logout_uri']) ? (string) $data['frontchannel_logout_uri'] : null,
        );
    }
}
